   [215]={next_id=216, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她微微蹙着眉，嘴唇红润，眼中泛着盈盈水光。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [216]={next_id=217, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊芙特双手抵在你的胸口，仰头看着你，林中的风裹挟着湿气扑到你脸上，一时间你都分不清脸上的湿意到底是她的亲吻还是大自然的馈赠。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [217]={next_id=218, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她抬起了双臂，因为这个动作，衣物都被挤出了褶皱。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [218]={next_id=219, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="娇贵的大小姐在这个时候也要任性，她压着你让你靠在了身后的树干上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT201_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
